/** Shapes of the seed JSON files (story.json, community.json). Generated by generate-seed.mjs. */
import type { ActionTypeId, AppNotification, CropId, I18nText, LatLng, LeaderboardScope, Member, OrgKind, Period, ScreenId, StageId, TeamEvidence, TeamTask, TreeHealth, VerificationStatus } from '../types';
import type { VerifyPhotoResult } from '@/lib/data/local/v0-types';

export type PeriodPoints = Record<Period, number>;

export type SeedStoryAction = {
  id: string;
  days_ago: number;
  action_type: ActionTypeId;
  quantity: number;
  status: VerificationStatus;
  team_id: string | null;
  goal_id: string | null;
  zone_label: string | null;
  note: string | null;
  photo_url: string | null;
  lat: number;
  lng: number;
  verification: VerifyPhotoResult;
  points: number;
  cooling_c: number;
  trees: number;
};

export type SeedStory = {
  user: { id: string; display_name: string; email: string; first_name: Record<'en' | 'bn' | 'ur', string> };
  profile: { home: LatLng; radius_m: number };
  goal: {
    id: string;
    zone_id: string;
    zone_name: string;
    zone_centroid: LatLng;
    zone_area_km2: number;
    target_c: number;
    by_date: string;
    progress_pct: number;
    modeled_c: number;
    team_id: string | null;
    org_id: string | null;
    created_days_ago: number;
  };
  trees: {
    id: string;
    species_id: string;
    nickname: string;
    planted_days_ago: number;
    last_check_days_ago: number | null;
    location: LatLng;
    health: TreeHealth;
    photo_url: string | null;
  }[];
  checks: { id: string; tree_id: string; days_ago: number; health: TreeHealth; note: string | null; photo_url: string | null; points: number }[];
  actions: SeedStoryAction[];
  memberships: { team_id: string; role: 'owner' | 'admin' | 'member'; joined_days_ago: number }[];
  fields: { id: string; name: string; crop: CropId; stage: StageId; location: LatLng; area: number; created_days_ago: number }[];
  sensors: { id: string; name: string; model: string; location: LatLng; created_days_ago: number }[];
  notifications: (Pick<AppNotification, 'id' | 'kind' | 'read'> & {
    title: I18nText;
    body: I18nText | null;
    screen: ScreenId | null;
    params?: Record<string, string>;
    days_ago: number;
  })[];
};

export type SeedBoardRow = { id: string; name: string; emoji?: string; points: number; trees: number; cooling_c: number };

/** `tail`: [points, rank] pairs, descending points, to estimate ranks below the explicit rows. */
export type SeedBoard = { rows: SeedBoardRow[]; tail: [number, number][] };

export type SeedTeam = {
  id: string;
  name: string;
  code: string;
  emoji: string;
  description: string;
  org_id: string | null;
  owner_id: string;
  max_members: number;
  is_public: boolean;
  area: string;
  city: string;
  country: string;
  goal_id: string | null;
  members: Member[];
  base: { points: number; trees: number; actions: number; cooling_c: number };
  activity: { id: string; user_name: string; action_type: ActionTypeId; quantity: number; points: number; days_ago: number }[];
  tasks: TeamTask[];
  evidence: TeamEvidence[];
  period_points: PeriodPoints;
};

export type SeedOrg = {
  id: string;
  name: string;
  kind: OrgKind;
  city: string;
  country: string;
  verified: boolean;
  description: string;
  since: string;
  logo_emoji: string;
  team_ids: string[];
  goals: { zone_name: string; target_c: number; by_date: string; progress_pct: number }[];
  period_points: PeriodPoints;
};

export type SeedCommunity = {
  area: string;
  city: string;
  country: string;
  teams: SeedTeam[];
  orgs: SeedOrg[];
  rising: { team_id: string; name: string; up: number; note: string }[];
  boards: Record<'user' | 'team' | 'org', Record<LeaderboardScope, Record<Period, SeedBoard>>>;
};
